{
  "findings": [
    {
      "check_id": "CKV2_AWS_40",
      "title": "Ensure AWS IAM policy does not allow full IAM privileges",
      "resource": "aws_iam_policy.privesc-ssmStartSession-policy",
      "severity": "MEDIUM",
      "explanation": "The IAM policy allows '*' as Resource for 'ssm:*' and 'ec2:*' actions which could potentially grant full IAM privileges or excessive permissions."
    }
  ],
  "patched_code": "resource "aws_iam_policy" "privesc-ssmStartSession-policy" {
  name        = "privesc-ssmStartSession-policy"
  path        = "/"
  description = "Allows privesc via targeted ssm"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action = [
          "ec2:DescribeInstances",
          "ssm:StartSession",
           "ssm:DescribeSessions",
            "ssm:GetConnectionStatus",
            "ssm:DescribeInstanceProperties",
            "ssm:TerminateSession",
            "ssm:ResumeSession"
        ]
        Resource = "arn:aws:ec2:*:*:instance/*"
      },
      {
        Effect   = "Allow"
        Action = [
          "ssm:StartSession",
          "ssm:TerminateSession",
          "ssm:ResumeSession"
        ]
        Resource = "arn:aws:ssm:*:*:session/*"
      },
      {
        Effect   = "Allow"
        Action = [
          "ssm:DescribeSessions",
          "ssm:GetConnectionStatus",
          "ssm:DescribeInstanceProperties"
        ]
        Resource = "*"
      }
    ]
  })
}",
  "fix_summary": "Restricted the Resource field in the IAM policy to specific ARNs where applicable, reducing the scope of permissions granted by the policy."
}
